<script setup>
import { ref, computed, onMounted } from 'vue'
const user=ref(null),page=ref('plaza'),error=ref(''),success=ref(''),mode=ref('login')
const credentials=ref({account:'',password:''}), profile=ref({}),passwords=ref({current_password:'',new_password:''})
const securityForm=ref({password:'',questions:[{question:'',answer:''},{question:'',answer:''},{question:'',answer:''}]}),resetForm=ref({account:'',answers:['','',''],new_password:''}),resetQuestions=ref([])
const adminData=ref({users:[],needs:[],invitations:[]}),adminSearch=ref('')
const trending=ref([]),detail=ref(null),messages=ref([]),adminDrafts=ref({})
const needs=ref([]),myNeeds=ref([]),matches=ref([]),invitations=ref([]),selectedNeed=ref(''),person=ref(null),contacts=ref({})
const categories=['学习','运动','兴趣','技能互助','项目组队'],days=['周一','周二','周三','周四','周五','周六','周日'],genders=['','男','女','其他','不愿透露'],grades=['','大一','大二','大三','大四','大五','研一','研二','研三','博士','其他']
const query=ref(''),categoryFilter=ref(''),newNeed=ref({category:'学习',title:'',description:'',tags:'',day:'周六',start:'14:00',duration:'120',end:'16:00'})
const incoming=computed(()=>invitations.value.filter(i=>i.receiver_id===user.value?.id&&i.status!=='accepted'))
const outgoing=computed(()=>invitations.value.filter(i=>i.sender_id===user.value?.id&&i.status!=='accepted'))
const accepted=computed(()=>invitations.value.filter(i=>i.status==='accepted'))
const visibleNeeds=computed(()=>needs.value.filter(n=>(!categoryFilter.value||n.category===categoryFilter.value)&&(!query.value||(n.title+n.description+n.tags.join(' ')).toLowerCase().includes(query.value.toLowerCase()))))
const split=s=>[...new Set(String(s||'').split(/[,，、]/).map(x=>x.trim()).filter(Boolean))]
const time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`
const minute=s=>Number(s.slice(0,2))*60+Number(s.slice(3))
const times=Array.from({length:35},(_,i)=>time(360+i*30))
async function api(path,method='GET',data){const res=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json'},credentials:'same-origin',body:data===undefined?undefined:JSON.stringify(data)});let value={};try{value=await res.json()}catch{}if(!res.ok)throw Error(value.error||(res.status>=500?'服务暂时不可用，请检查 Docker 后端是否已启动':'请求失败'));return value}
function message(text,kind='success'){error.value=kind==='error'?text:'';success.value=kind==='success'?text:'';setTimeout(()=>{error.value='';success.value=''},4000)}
async function auth(){try{if(mode.value==='register'){const r=await api('/register','POST',{email:credentials.value.account,password:credentials.value.password});message('注册成功，账号 ID：'+r.account_id);mode.value='login';credentials.value.password=''}else{await api('/login','POST',credentials.value);credentials.value.password='';await refresh()}}catch(e){message(e.message,'error')}}
async function saveSecurityQuestions(){try{await api('/security-questions','POST',securityForm.value);securityForm.value={password:'',questions:[{question:'',answer:''},{question:'',answer:''},{question:'',answer:''}]};message('密保问题已保存')}catch(e){message(e.message,'error')}}
async function loadResetQuestions(){try{resetQuestions.value=(await api('/security-questions?account='+encodeURIComponent(resetForm.value.account))).questions;resetForm.value.answers=['','','']}catch(e){message(e.message,'error')}}
async function resetPassword(){try{await api('/reset-password','POST',resetForm.value);resetForm.value={account:'',answers:['','',''],new_password:''};resetQuestions.value=[];mode.value='login';message('密码已重置，请重新登录')}catch(e){message(e.message,'error')}}
async function refresh(){try{const r=await api('/me');user.value=r.user;if(page.value==='admin'&&!r.user.admin)page.value='plaza';if(r.user.admin&&(page.value==='recommend'||page.value==='invitations'))page.value='admin';profile.value={...r.user,personality:r.user.personality.join('，'),interests:r.user.interests.join('，'),skills:r.user.skills.join('，'),wants:r.user.wants.join('，')};await go(page.value)}catch{user.value=null}}
async function go(target){page.value=target;error.value='';try{if(target==='plaza'){needs.value=(await api('/needs')).needs;trending.value=(await api('/trending')).topics}if(target==='recommend'){myNeeds.value=(await api('/my-needs')).needs;selectedNeed.value=String(myNeeds.value.find(n=>n.status==='open')?.id||'');await loadMatches()}if(target==='invitations')invitations.value=(await api('/invitations')).invitations;if(target==='messages')messages.value=(await api('/messages')).messages;if(target==='admin')adminData.value=await api('/admin/overview')}catch(e){message(e.message,'error')}}
async function openDetail(n){try{detail.value=(await api('/needs/'+n.id)).need;const item=needs.value.find(x=>x.id===n.id);if(item)item.views=detail.value.views}catch(e){message(e.message,'error')}}
async function adminUserAction(u){try{await api('/admin/users/'+u.id,'PATCH',{action:u.disabled?'enable':'disable'});await go('admin');message(u.disabled?'账号已恢复':'账号已停用')}catch(e){message(e.message,'error')}}
async function adminCloseNeed(n){try{await api('/admin/needs/'+n.id,'PATCH',{action:'remove'});await go('admin');message('帖子已撤下')}catch(e){message(e.message,'error')}}
async function adminSendMessage(n){try{await api('/admin/messages','POST',{need_id:n.id,body:adminDrafts.value[n.id]});adminDrafts.value[n.id]='';message('私信已发送给发布者')}catch(e){message(e.message,'error')}}
const filteredAdminUsers=computed(()=>adminData.value.users.filter(u=>[u.account_id,u.name].some(x=>String(x||'').toLowerCase().includes(adminSearch.value.toLowerCase()))))
async function loadMatches(){matches.value=selectedNeed.value?(await api('/recommend/'+selectedNeed.value)).matches:[]}
async function publish(){try{const n=newNeed.value;let end=n.duration==='custom'?n.end:time(minute(n.start)+Number(n.duration));await api('/needs','POST',{category:n.category,title:n.title,description:n.description,tags:split(n.tags),slots:[{day:n.day,start:n.start,end}]});newNeed.value={category:'学习',title:'',description:'',tags:'',day:'周六',start:'14:00',duration:'120',end:'16:00'};message('需求已发布');await go(page.value)}catch(e){message(e.message,'error')}}
async function deleteNeed(n){if(!window.confirm(`确定删除「${n.title}」吗？待处理的邀请会撤回。`))return;try{await api('/needs/'+n.id,'DELETE');message('需求已删除');await go('recommend')}catch(e){message(e.message,'error')}}
async function toggleNeed(n){try{await api('/needs/'+n.id,'PATCH',{status:n.status==='open'?'closed':'open'});await go('recommend')}catch(e){message(e.message,'error')}}
async function sendInvite(needId,receiverId){try{await api('/invitations','POST',{need_id:needId,receiver_id:receiverId});message('邀请已发出')}catch(e){message(e.message,'error')}}
async function action(i,type){try{await api('/invitations/'+i.id,'PATCH',{action:type});message('邀请已处理');await go('invitations')}catch(e){message(e.message,'error')}}
async function showContacts(i){try{contacts.value={...contacts.value,[i.id]:(await api('/contacts/'+i.id)).contacts}}catch(e){message(e.message,'error')}}
async function showPerson(id){try{person.value=(await api('/users/'+id)).user}catch(e){message(e.message,'error')}}
async function saveProfile(){try{const p={...profile.value};for(const k of ['personality','interests','skills','wants'])p[k]=split(p[k]);await api('/me','PATCH',p);message('资料已保存');await refresh()}catch(e){message(e.message,'error')}}
async function changePassword(){try{await api('/password','PATCH',passwords.value);passwords.value={current_password:'',new_password:''};message('密码已修改，其他设备需要重新登录')}catch(e){message(e.message,'error')}}
async function logout(){try{await api('/logout','POST')}finally{user.value=null;page.value='plaza';adminData.value={users:[],needs:[],invitations:[]}}}
onMounted(refresh)
</script>

<template>
<div class="shell">
  <header><div class="brand"><span class="brand-icon">✦</span><div><strong>校园搭子</strong><small>找到同频的人，一起出发</small></div></div><nav v-if="user"><button v-for="x in [['plaza','需求广场'],...(!user.admin?[['recommend','匹配推荐'],['invitations','我的邀请']]:[]),['messages','站内信'],['profile','个人资料'],...(user.admin?[['admin','管理端']]:[])]" :key="x[0]" :class="{active:page===x[0]}" @click="go(x[0])">{{x[1]}}</button></nav><div v-if="user" class="header-user">{{user.name}} <button @click="logout">退出</button></div></header>
  <main v-if="!user" class="auth-wrap"><section class="hero"><span class="eyebrow">CAMPUS CONNECTION</span><h1>下一次同行，<br>从这里开始。</h1><p>找学习、运动、兴趣与技能互助搭子。只有双方同意后，才能查看彼此联系方式。</p><div class="hero-pills"><span>✎ 一起学习</span><span>◉ 一起运动</span><span>✦ 交换技能</span></div></section><form v-if="mode!=='reset'" class="auth-card" @submit.prevent="auth"><h2>{{mode==='login'?'欢迎回来':'创建账号'}}</h2><p>{{mode==='login'?'使用邮箱或账号 ID 登录。':'用邮箱注册，无需验证码。'}}</p><div class="tabs"><button type="button" :class="{active:mode==='login'}" @click="mode='login'">登录</button><button type="button" :class="{active:mode==='register'}" @click="mode='register'">注册</button></div><label>{{mode==='login'?'邮箱或账号 ID':'邮箱'}}<input v-model="credentials.account" :type="mode==='register'?'email':'text'" :autocomplete="mode==='register'?'email':'username'" required></label><label>密码<input v-model="credentials.password" type="password" :autocomplete="mode==='login'?'current-password':'new-password'" minlength="8" required></label><button class="primary full" type="submit">{{mode==='login'?'登录':'注册'}}</button><button v-if="mode==='login'" type="button" @click="mode='reset'">忘记密码？</button></form><form v-else class="auth-card" @submit.prevent="resetPassword"><h2>重置密码</h2><p>先输入账号，回答预先设置的 3 个密保问题；答对其中 2 个即可重置。</p><label>邮箱或账号 ID<input v-model="resetForm.account" required></label><button type="button" @click="loadResetQuestions">查看密保问题</button><template v-if="resetQuestions.length===3"><label v-for="(q,index) in resetQuestions" :key="q.question_no">{{q.question}}<input v-model="resetForm.answers[index]" autocomplete="off"></label><label>新密码<input v-model="resetForm.new_password" type="password" minlength="8" autocomplete="new-password" required></label><button class="primary full" type="submit">重置密码</button></template><button type="button" @click="mode='login'">返回登录</button></form></main>
  <main v-else class="main"><div class="page-heading"><span class="eyebrow">CAMPUS BUDDY</span><h1>{{{plaza:'需求广场',recommend:'匹配推荐',invitations:'我的邀请',messages:'站内信',profile:'个人资料',admin:'管理端'}[page]}}</h1><p>{{{plaza:'看看大家正在寻找怎样的搭子。',recommend:'根据共同时间、兴趣与技能找到候选。',invitations:'每一次连接，都由双方共同决定。',messages:'查看管理员发来的通知。',profile:'介绍自己，让合适的人更容易找到你。',admin:'查看用户、需求与邀请，并处理需要管理的内容。'}[page]}}</p></div>
    <div v-if="page==='plaza'"><section class="trending"><h2>热门搭子主题 · 近 7 天</h2><div v-if="trending.length" class="trend-list"><button v-for="t in trending" :key="t.topic" @click="categoryFilter='';query=t.topic"><strong>{{t.topic}}搭子</strong><span>{{t.posts}} 条需求 · {{t.views_7d}} 次浏览</span></button></div><p v-else class="empty">最近还没有形成热门主题。</p></section><div class="toolbar"><input v-model="query" placeholder="搜索需求关键词"><select v-model="categoryFilter"><option value="">全部类型</option><option v-for="c in categories" :key="c">{{c}}</option></select><span>{{visibleNeeds.length}} 条需求</span></div><div class="grid"><article v-for="n in visibleNeeds" :key="n.id" class="card"><div class="card-top"><span class="badge">{{n.category}}</span><small>{{n.owner_name}} · {{n.views||0}} 次浏览</small></div><h3>{{n.title}}</h3><p>{{n.description||'期待找到合适的搭子，一起开始。'}}</p><div class="tags"><span v-for="t in n.tags" :key="t">{{t}}</span><span v-for="s in n.slots" :key="s.day+s.start">{{s.day}} {{s.start}}–{{s.end}}</span></div><div class="actions"><button @click="openDetail(n)">查看详情</button><button v-if="n.user_id!==user.id" @click="showPerson(n.user_id)">查看资料</button><button v-if="n.user_id!==user.id" class="primary" @click="sendInvite(n.id,n.user_id)">发送邀请</button></div></article></div><div v-if="!visibleNeeds.length" class="empty">暂无相关需求，发布一条试试。</div></div>
    <div v-if="page==='recommend'"><div class="panel"><h2>发布新需求</h2><form class="need-form" @submit.prevent="publish"><div class="form-grid"><label>类型<select v-model="newNeed.category"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>标题<input v-model="newNeed.title" minlength="3" maxlength="60" required></label><label class="span2">说明<textarea v-model="newNeed.description" maxlength="500" rows="2"></textarea></label><label class="span2">标签（逗号分隔）<input v-model="newNeed.tags" placeholder="例如 羽毛球，Python"></label><label>星期<select v-model="newNeed.day"><option v-for="d in days" :key="d">{{d}}</option></select></label><label>开始时间<select v-model="newNeed.start"><option v-for="t in times" :key="t">{{t}}</option></select></label><label>时长<select v-model="newNeed.duration"><option value="60">1 小时</option><option value="120">2 小时</option><option value="180">3 小时</option><option value="custom">自选结束时间</option></select></label><label v-if="newNeed.duration==='custom'">结束时间<select v-model="newNeed.end"><option v-for="t in times" :key="t">{{t}}</option></select></label></div><button class="primary" type="submit">发布需求</button></form></div><div class="panel"><h2>我的需求</h2><div v-for="n in myNeeds" :key="n.id" class="list-row"><div><strong>{{n.title}}</strong><small>{{n.category}} · {{n.status==='open'?'开放中':n.status==='removed'?'管理员已撤下':'已关闭'}}</small></div><div class="actions"><button v-if="n.status!=='removed'" @click="toggleNeed(n)">{{n.status==='open'?'关闭':'重新开放'}}</button><button class="danger" @click="deleteNeed(n)">删除</button></div></div><div v-if="!myNeeds.length" class="empty">还没有发布需求。</div></div><div class="panel"><h2>匹配推荐</h2><select v-model="selectedNeed" @change="loadMatches"><option value="">选择开放的需求</option><option v-for="n in myNeeds.filter(x=>x.status==='open')" :key="n.id" :value="String(n.id)">{{n.title}}</option></select><div class="grid matches"><article v-for="m in matches" :key="m.user.id" class="card"><div class="card-top"><span class="badge">搭子候选</span><strong class="score">{{m.score}} 分</strong></div><h3>{{m.user.name}}</h3><p>{{m.user.bio}}</p><div class="tags"><span v-for="t in [...m.user.personality,...m.user.interests]" :key="t">{{t}}</span></div><p v-for="reason in m.reasons" :key="reason" class="reason">{{reason}}</p><div class="actions"><button @click="showPerson(m.user.id)">查看资料</button><button class="primary" @click="sendInvite(Number(selectedNeed),m.user.id)">邀请 TA</button></div></article></div><div v-if="selectedNeed&&!matches.length" class="empty">暂无共同时间的候选。</div></div></div>
    <div v-if="page==='invitations'"><div class="panel"><h2>收到的申请</h2><div v-for="i in incoming" :key="i.id" class="list-row"><div><strong>{{i.need_title}}</strong><small>来自 {{i.sender_name}} · {{i.status}}</small></div><div class="actions"><button @click="showPerson(i.sender_id)">查看资料</button><button v-if="i.status==='pending'" class="primary" @click="action(i,'accepted')">同意</button><button v-if="i.status==='pending'" @click="action(i,'rejected')">拒绝</button></div></div><div v-if="!incoming.length" class="empty">还没有收到申请。</div></div><div class="panel"><h2>发出的邀请</h2><div v-for="i in outgoing" :key="i.id" class="list-row"><div><strong>{{i.need_title}}</strong><small>发给 {{i.receiver_name}} · {{i.status}}</small></div><div class="actions"><button @click="showPerson(i.receiver_id)">查看资料</button><button v-if="i.status==='pending'" @click="action(i,'withdrawn')">撤回</button></div></div><div v-if="!outgoing.length" class="empty">还没有发出邀请。</div></div><div class="panel"><h2>匹配成功记录</h2><div v-for="i in accepted" :key="i.id" class="list-row"><div><strong>{{i.need_title}}</strong><small>{{i.sender_name}} 与 {{i.receiver_name}} 已同意</small><div v-if="contacts[i.id]" class="contact-list"><div v-for="c in contacts[i.id]" :key="c.name"><strong>{{c.name}}</strong><span v-if="c.email">邮箱：{{c.email}}</span><span v-if="c.phone">电话：{{c.phone}}</span><span v-if="c.wechat">微信：{{c.wechat}}</span><span v-if="c.qq">QQ：{{c.qq}}</span></div></div></div><button @click="showContacts(i)">查看联系方式</button></div><div v-if="!accepted.length" class="empty">双方同意后会显示在这里。</div></div></div>
    <div v-if="page==='profile'" class="profile-grid"><form class="panel" @submit.prevent="saveProfile"><h2>我的资料</h2><div class="form-grid"><label>昵称<input v-model="profile.name" maxlength="30" required></label><label>年龄<input v-model="profile.age" type="number" min="16" max="100"></label><label>性别<select v-model="profile.gender"><option v-for="g in genders" :key="g" :value="g">{{g||'暂不填写'}}</option></select></label><label>年级<select v-model="profile.grade"><option v-for="g in grades" :key="g" :value="g">{{g||'暂不填写'}}</option></select></label><label>家乡<input v-model="profile.hometown" maxlength="40"></label><label class="span2">个人介绍<textarea v-model="profile.bio" rows="3" maxlength="300"></textarea></label><label class="span2">性格特点<input v-model="profile.personality" placeholder="开朗，耐心"></label><label>兴趣<input v-model="profile.interests"></label><label>擅长技能<input v-model="profile.skills"></label><label class="span2">想学习的技能<input v-model="profile.wants"></label></div><h3>联系方式</h3><div class="form-grid"><label>联系邮箱<input v-model="profile.contact_email" type="email"></label><label>电话<input v-model="profile.phone" type="tel"></label><label>微信<input v-model="profile.wechat"></label><label>QQ<input v-model="profile.qq" inputmode="numeric"></label></div><button class="primary" type="submit">保存资料</button></form><div class="panel"><h2>账号信息</h2><p>账号 ID：<strong>{{user.account_id}}</strong></p><p>注册邮箱：<strong>{{user.email}}</strong></p><form @submit.prevent="changePassword"><h3>修改密码</h3><label>当前密码<input v-model="passwords.current_password" type="password" required></label><label>新密码<input v-model="passwords.new_password" type="password" minlength="8" required></label><button type="submit">修改密码</button></form><form @submit.prevent="saveSecurityQuestions"><h3>设置密保问题</h3><p>忘记密码时，答对任意 2 个问题即可重置。请设置不容易被别人猜到的答案。</p><label>当前密码<input v-model="securityForm.password" type="password" required></label><div v-for="(item,index) in securityForm.questions" :key="index"><label>问题 {{index+1}}<input v-model="item.question" minlength="4" maxlength="100" required></label><label>答案 {{index+1}}<input v-model="item.answer" minlength="2" maxlength="100" autocomplete="off" required></label></div><button type="submit">保存密保问题</button></form></div></div>
    <div v-if="page==='messages'" class="panel"><h2>我的站内信</h2><div v-for="m in messages" :key="m.id" class="admin-row"><div><strong>{{m.sender_name}} · 关于「{{m.need_title}}」</strong><small>{{m.created_at}}</small><p>{{m.body}}</p></div></div><div v-if="!messages.length" class="empty">暂无站内信。</div></div>
    <div v-if="page==='admin'" class="admin-page">
      <div class="admin-stats"><div class="panel"><strong>{{adminData.users.length}}</strong><span>用户</span></div><div class="panel"><strong>{{adminData.needs.length}}</strong><span>需求</span></div><div class="panel"><strong>{{adminData.invitations.length}}</strong><span>匹配成功</span></div></div>
      <section class="panel"><h2>用户管理</h2><p>管理员可查看公开资料和状态，不查看用户联系方式。停用账号会让该用户退出，恢复后可重新登录。</p><input v-model="adminSearch" placeholder="搜索账号 ID 或昵称"><div v-for="u in filteredAdminUsers" :key="u.id" class="admin-row"><div><strong>{{u.name}}</strong><small>账号 ID：{{u.account_id}} · {{u.created_at}}</small><small>年龄：{{u.age||'未填'}} · 性别：{{u.gender||'未填'}} · 年级：{{u.grade||'未填'}} · 家乡：{{u.hometown||'未填'}}</small><small>介绍：{{u.bio||'未填'}}</small></div><div class="actions"><span v-if="u.admin" class="badge">管理员</span><button v-else @click="adminUserAction(u)">{{u.disabled?'恢复账号':'停用账号'}}</button></div></div><div v-if="!filteredAdminUsers.length" class="empty">没有匹配的用户。</div></section>
      <section class="panel"><h2>需求管理</h2><div v-for="n in adminData.needs" :key="n.id" class="admin-row"><div><strong>{{n.title}}</strong><small>{{n.owner_name}} · {{n.category}} · {{n.status}} · {{n.created_at}}</small><p>{{n.description}}</p></div><div class="admin-moderation"><textarea v-model="adminDrafts[n.id]" rows="2" maxlength="500" placeholder="给发布者发送站内私信"></textarea><button @click="adminSendMessage(n)" :disabled="!adminDrafts[n.id]?.trim()">发送私信</button><button v-if="n.status!=='removed'" @click="adminCloseNeed(n)">撤下帖子</button></div></div><div v-if="!adminData.needs.length" class="empty">暂无需求。</div></section>
      <section class="panel"><h2>用户需求匹配成功记录</h2><div v-for="i in adminData.invitations" :key="i.id" class="admin-row"><div><strong>#{{i.id}} · {{i.sender_name}} → {{i.receiver_name}}</strong><small>需求「{{i.need_title}}」 · {{i.created_at}}</small></div></div><div v-if="!adminData.invitations.length" class="empty">暂无匹配成功记录。</div></section>
    </div>
  </main>
  <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><div class="modal"><button class="close" @click="detail=null">×</button><span class="badge">{{detail.category}}</span><h2>{{detail.title}}</h2><p>{{detail.description}}</p><div class="tags"><span v-for="t in detail.tags" :key="t">{{t}}</span><span v-for="t in detail.slots" :key="t.day+t.start">{{t.day}} {{t.start}}–{{t.end}}</span></div><small>{{detail.owner_name}} · {{detail.views}} 次浏览</small></div></div>
  <div v-if="person" class="modal-backdrop" @click.self="person=null"><div class="modal"><button class="close" @click="person=null">×</button><h2>{{person.name}}</h2><p>{{[person.age?person.age+' 岁':'',person.gender,person.grade,person.hometown?`家乡：${person.hometown}`:''].filter(Boolean).join(' · ')}}</p><p>{{person.bio}}</p><p v-if="person.personality.length">性格：{{person.personality.join('、')}}</p><p v-if="person.interests.length">兴趣：{{person.interests.join('、')}}</p><p v-if="person.skills.length">擅长：{{person.skills.join('、')}}</p><p v-if="person.wants.length">想学习：{{person.wants.join('、')}}</p><small>联系方式仅在双方同意后开放。</small></div></div>
  <div v-if="error||success" class="toast" :class="{bad:!!error}">{{error||success}}</div>
</div>
</template>
